package com.ejemplo.calculator

internal enum class Idioma(
    val codigo: String,
    val bandera: String,
    val nombre: String
) {
    RUSO("ru", "🇷🇺", "Русский"),
    INGLES("en", "🇬🇧", "English"),
    ALEMAN("de", "🇩🇪", "Deutsch"),
    CHINO("zh", "🇨🇳", "中文"),
    LETON("lv", "🇱🇻", "Latviešu"),
    BELARUSO("be", "🇧🇾", "Беларуская"),
    UCRANIANO("uk", "🇺🇦", "Українська"),
    TURCO("tr", "🇹🇷", "Türkçe");

    companion object {
        fun porCodigo(codigo: String?): Idioma =
            values().firstOrNull { it.codigo == codigo } ?: RUSO
    }
}

internal object Textos {
    var idioma: Idioma = Idioma.RUSO

    fun tr(texto: String): String {
        if (idioma == Idioma.RUSO) return texto
        val fila = TRADUCCIONES[texto] ?: return texto
        return fila.split('|').getOrElse(idioma.ordinal - 1) { texto }
    }

    fun formaTiempo(cantidad: Double, unidad: UnidadTiempo): String {
        val entero = cantidad.toLong()
        val esEntero = cantidad == entero.toDouble()
        return when (idioma) {
            Idioma.RUSO, Idioma.BELARUSO, Idioma.UCRANIANO -> {
                if (!esEntero) {
                    tr(unidad.pocos)
                } else {
                    val mod100 = (entero % 100).toInt()
                    val mod10 = (entero % 10).toInt()
                    when {
                        mod100 in 11..14 -> tr(unidad.muchos)
                        mod10 == 1 -> tr(unidad.uno)
                        mod10 in 2..4 -> tr(unidad.pocos)
                        else -> tr(unidad.muchos)
                    }
                }
            }
            Idioma.LETON -> {
                if (esEntero && entero % 10 == 1L && entero % 100 != 11L) {
                    tr(unidad.uno)
                } else {
                    tr(unidad.pocos)
                }
            }
            Idioma.INGLES, Idioma.ALEMAN -> {
                if (esEntero && entero == 1L) tr(unidad.uno) else tr(unidad.pocos)
            }
            Idioma.CHINO, Idioma.TURCO -> tr(unidad.pocos)
        }
    }

